package net.kdt.pojavlaunch.profiles;
import android.content.Context;import com.kdt.mcgui.ProgressLayout;import net.kdt.pojavlaunch.Tools;import net.kdt.pojavlaunch.progresskeeper.*;import net.kdt.pojavlaunch.utils.DownloadControl;import net.kdt.pojavlaunch.value.launcherprofiles.*;import java.util.*;import java.util.concurrent.*;
/** Profile-keyed mirror of existing download records; never starts a second download. */
public final class ProfileInstallProgress{
 public static final class State{public final String profileKey;public final String record;public final boolean creating;public volatile int percent;public volatile String status="PREPARING PROFILE",detail="";public volatile int currentFile,totalFiles;public volatile double currentMb,totalMb,speed,eta;public volatile boolean paused,failed;State(String k,String r,boolean c){profileKey=k;record=r;creating=c;}}
 public interface Listener{void onProfileInstallChanged(String key);}
 private static final ConcurrentHashMap<String,State>STATES=new ConcurrentHashMap<>();private static final ConcurrentHashMap<String,ProgressListener>HOOKS=new ConcurrentHashMap<>();private static final CopyOnWriteArrayList<Listener>LISTENERS=new CopyOnWriteArrayList<>();private static final ConcurrentHashMap<String,Integer>LAST_SAVED=new ConcurrentHashMap<>();private ProfileInstallProgress(){}
 public static void addListener(Listener l){if(l!=null&&!LISTENERS.contains(l))LISTENERS.add(l);}public static void removeListener(Listener l){LISTENERS.remove(l);}public static State get(String key){State s=STATES.get(key);if(s!=null)return s;MinecraftProfile p=LauncherProfiles.mainProfileJson==null?null:LauncherProfiles.mainProfileJson.profiles.get(key);if(p!=null&&p.installing){s=new State(key,p.installRecord,true);s.percent=p.installProgress;s.status=p.installStatus==null?"INSTALL INTERRUPTED":p.installStatus;s.failed=true;STATES.put(key,s);}return s;}
 public static State beginDirect(String key,String controlRecord,boolean creating,String status){State old=STATES.remove(key);detach(key,old);State s=new State(key,controlRecord,creating);if(status!=null)s.status=status;STATES.put(key,s);persist(s,true);notifyKey(key);return s;}
 public static State begin(String key,String record,boolean creating,String status){State old=STATES.remove(key);detach(key,old);State s=new State(key,record,creating);if(status!=null)s.status=status;STATES.put(key,s);persist(s,true);if(record!=null){ProgressListener hook=new ProgressListener(){boolean started;public void onProgressStarted(){started=true;notifyKey(key);}public void onProgressUpdated(int pct,int resid,Object...v){started=true;updateFromRecord(s,pct,resid,v);}public void onProgressEnded(){if(started&&!s.failed)complete(key);}};HOOKS.put(key,hook);ProgressKeeper.addListener(record,hook);}notifyKey(key);return s;}
 private static void updateFromRecord(State s,int pct,int resid,Object...v){s.percent=Math.max(0,Math.min(99,pct));if(v!=null&&v.length>=9){try{s.currentMb=((Number)v[1]).doubleValue();s.totalMb=((Number)v[2]).doubleValue();s.speed=((Number)v[3]).doubleValue();s.eta=((Number)v[4]).doubleValue();String name=(String)v[5];if(name!=null&&!name.isEmpty())s.detail=name;}catch(Throwable ignored){}}s.status=s.paused?"PAUSED":(s.detail==null||s.detail.isEmpty()?"INSTALLING FILES":"DOWNLOADING "+s.detail);persist(s,false);notifyKey(s.profileKey);}
 public static void update(String key,int pct,String status,String detail,int current,int total){State s=STATES.get(key);if(s==null)return;s.percent=Math.max(0,Math.min(99,pct));if(status!=null)s.status=status;if(detail!=null)s.detail=detail;s.currentFile=current;s.totalFiles=total;persist(s,false);notifyKey(key);}
 public static void complete(String key){State s=STATES.get(key);if(s==null)return;s.percent=100;s.status="PROFILE READY";s.failed=false;persist(s,true);notifyKey(key);Tools.MAIN_HANDLER.postDelayed(()->{State x=STATES.remove(key);detach(key,x);notifyKey(key);},900);}
 public static void fail(String key,String message){State s=STATES.get(key);if(s==null)return;s.failed=true;s.status=message==null?"INSTALLATION FAILED":message;persist(s,true);notifyKey(key);}
 public static void togglePause(String key){State s=STATES.get(key);if(s==null||s.record==null)return;s.paused=!s.paused;DownloadControl.requestPause(s.record,s.paused);s.status=s.paused?"PAUSED":"RESUMING";notifyKey(key);}public static void stop(String key){State s=STATES.get(key);if(s==null)return;if(s.record!=null)DownloadControl.requestCancel(s.record);s.failed=true;s.status="STOPPING…";persist(s,true);notifyKey(key);}
 private static void detach(String key,State s){ProgressListener h=HOOKS.remove(key);if(h!=null&&s!=null&&s.record!=null)ProgressKeeper.removeListener(s.record,h);}
 private static synchronized void persist(State s,boolean force){MinecraftProfile p=LauncherProfiles.mainProfileJson==null?null:LauncherProfiles.mainProfileJson.profiles.get(s.profileKey);if(p==null)return;p.installing=s.percent<100;p.installProgress=s.percent;p.installStatus=s.status;p.installRecord=s.record;int bucket=s.percent/5;if(force||LAST_SAVED.getOrDefault(s.profileKey,-1)!=bucket){LAST_SAVED.put(s.profileKey,bucket);LauncherProfiles.write();}}
 private static void notifyKey(String key){Tools.runOnUiThread(()->{for(Listener l:LISTENERS)l.onProfileInstallChanged(key);});}
}
